// 用 child_process 跑 healthcheck.py (Code 节点内执行 python, 不用 executeCommand 节点)
const { execSync } = require('child_process');
const cmd = '/usr/bin/python3 /Users/jason/esd-n8n/bridge/healthcheck.py --product esd-rubber-mat';
try {
  const stdout = execSync(cmd, { encoding: 'utf-8', timeout: 90000 });
  const lastLine = stdout.trim().split('\n').pop() || '{}';
  let parsed = {};
  try { parsed = JSON.parse(lastLine); } catch (e) { parsed = { ok: false, error: '解析失败: ' + stdout.slice(-200) }; }
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { ok: false, healthy: false, error: String(e.message || e).slice(0, 300) } }];
}

// 异常 - 构造报警文本
const alertText = $json.alert || ('CRM同步异常: 本地 ' + $json.local_sent + ' / 飞书 ' + $json.feishu_records + ' 漂移 ' + $json.drift);
return [{ json: { alertText: alertText } }];

// 调 Hermes 8766 feishu-dm 端点发 DM 报警
const { fetch } = require('n8n-workflow');
const alertText = $json.alertText || 'CRM同步异常(无详情)';
const resp = await fetch('http://127.0.0.1:8766/feishu-dm', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ text: alertText })
});
const body = await resp.text();
return [{ json: { delivered: resp.ok, body: body.slice(0, 200), alertText: alertText } }];
